var maxPoints = function(technique1, technique2, k) {
    // return "hello";
    let n = technique1.length;
    if (k == 1 && technique1.length==1)
        {
            return technique1[0];
        }
    let total = 0;
    if (k == 0)
    {
        for (let i=0; i<n; i++)
        {
            total = total + Math.max(technique1[i],technique2[i]);
        }
        return total;
    }

    let trickleUp = function()
    {
        let index = values.length - 1;
        let [tech1, tech2, benefit] = values[index];

        while (index > 0)
        {
            let parentIndex = Math.floor((index-1)/2);
            let [parentTech1, parentTech2, parentBenefit] = values[parentIndex];

            if (benefit < parentBenefit)
            {
                break;
            }
            values[index] = [...values[parentIndex]];
            index = parentIndex;
        }
        values[index] = [...[tech1,tech2,benefit]];
    }
    let values = [];

    
    for (let i=0; i<n; i++)
    {
        values.push([technique1[i],technique2[i],technique1[i]-technique2[i]]);
        trickleUp();
    }
    // for (let item of values)
    // {
    //     console.log(item);
    // }

    
    let trickleDown = function(index)
    {
        let [tech1, tech2, benefit] = values[index];
        let largeIndex;

        while (index < values.length/2)
        {
            let leftIndex = 2*index + 1;
            let rightIndex = 2*index + 2;

            if (rightIndex<values.length && values[rightIndex][2]>=values[leftIndex][2])
            {
                largeIndex = rightIndex;
            }
            else
            {
                largeIndex = leftIndex;
            }
            if (values[largeIndex]==undefined || benefit>values[largeIndex][2])
            {
                break;
            }
            values[index] = [...values[largeIndex]];
            index = largeIndex;
        }
        values[index] = [...[tech1,tech2,benefit]];

    }
    for (let i=0; i<k; i++)
    {
        let [tech1Output, tech2Output, benefitOutput] = values[0];
        total = total + tech1Output;
        values[0] = [...values[values.length-1]];
        trickleDown(0);
        values.pop();
    }
    // console.log("#####");
    // for (let item of values)
    // {
    //     console.log(item);
    // }
    let N = values.length;
    for (let i=0; i<N; i++)
    {
        if (total+values[i][0] > total+values[i][1])
        {
            total = total + values[i][0];
        }
        else
        {
            total = total + values[i][1];
        }
    }
    return total;
};

